import{_ as a,o as t,c as o,a2 as c}from"./chunks/framework.BS0bAV7E.js";const s=JSON.parse('{"title":"TUI 引擎","description":"","frontmatter":{},"headers":[],"relativePath":"zh/arch/tui-engine.md","filePath":"zh/arch/tui-engine.md"}'),d={name:"zh/arch/tui-engine.md"};function i(r,e,n,h,_,l){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="tui-引擎" tabindex="-1">TUI 引擎 <a class="header-anchor" href="#tui-引擎" aria-label="Permalink to &quot;TUI 引擎&quot;">​</a></h1><p><code>tui/</code> 是一个在帧缓冲控制台上的窗口系统：</p><h2 id="核心" tabindex="-1">核心 <a class="header-anchor" href="#核心" aria-label="Permalink to &quot;核心&quot;">​</a></h2><p><code>tui_core.c</code>（事件循环 + 窗口管理器）、<code>tui_win.c</code>（窗口）、<code>tui_menu.c</code>、<code>tui_form.c</code>、<code>tui_panel.c</code>、<code>tui_text.c</code>（控件）、<code>tui_input.c</code>（键盘路由）、<code>tui_hw.c</code>（渲染诊断）。</p><h2 id="桌面" tabindex="-1">桌面 <a class="header-anchor" href="#桌面" aria-label="Permalink to &quot;桌面&quot;">​</a></h2><p><code>tui_desktop.c</code> + <code>tui_dt_*</code>：任务栏、启动器、应用程序（文件、编辑器、进程/系统监控器、网络状态、系统信息、时钟）。</p><h2 id="命令桥" tabindex="-1">命令桥 <a class="header-anchor" href="#命令桥" aria-label="Permalink to &quot;命令桥&quot;">​</a></h2><p><code>tui_cmd.c</code> 通过 L1 API 枚举 shell 命令表（任何 L1 模块均可枚举 - <code>l1_ext_shell_list_commands_a_z</code>），并将其渲染为启动器：扩展接口面的参考消费者。</p><h2 id="扩展接口面" tabindex="-1">扩展接口面 <a class="header-anchor" href="#扩展接口面" aria-label="Permalink to &quot;扩展接口面&quot;">​</a></h2><p><code>tui_ext.h</code> - 37 个可调用声明（窗口、菜单、表单、面板、文本）。L1 模块通过它构建 UI；CN 变体（<code>tui_cn_*.c</code>）展示了中文层在其下的模式。</p><h2 id="渲染路径" tabindex="-1">渲染路径 <a class="header-anchor" href="#渲染路径" aria-label="Permalink to &quot;渲染路径&quot;">​</a></h2><p>帧缓冲几何信息来自 multiboot2 帧缓冲标签；控制台网格和 8x16 字体引擎在 IDT 之前初始化（启动日志顺序很重要 - TUI 使用内核横幅使用的相同原语进行绘制）。<code>tui-test</code> 是针对所有这些的客内回归测试套件。</p>',12)])])}const p=a(d,[["render",i]]);export{s as __pageData,p as default};
